<p class="mb-4 text-dark-600 dark:text-dark-300 leading-relaxed">The difficulty arises when anger becomes <strong>too frequent, too intense, disproportionate to the situation, or difficult to control</strong>, particularly when it repeatedly harms your well-being or relationships.</p>
